effect.shader:
// Medidos no plugin (tools/vox/benchmark):
const float FOCO = 0.8660254;          // sem câmera na composição: o foco, em alturas do quadro (60° de campo vertical)
const int PASSOS = 64;        // quantas células da grade o raio atravessa, no máximo

vec2 tamanho() { return vec2(textureSize(inputImg, 0)); }

mat3 giro() {
    vec3 a = radians(vec3(rotationX, rotationY, rotationZ));
    vec3 s = sin(a), c = cos(a);
    mat3 rx = mat3(1.0, 0.0, 0.0, 0.0, c.x, s.x, 0.0, -s.x, c.x);
    mat3 ry = mat3(c.y, 0.0, -s.y, 0.0, 1.0, 0.0, s.y, 0.0, c.y);
    mat3 rz = mat3(c.z, s.z, 0.0, -s.z, c.z, 0.0, 0.0, 0.0, 1.0);
    return rz * ry * rx;
}

/**
 * Quanto do pixel o segmento (centro c, eixo e, meio-comprimento L, raio r + `folga` px) cobre; t = a
 * distância no raio. As pontas são retas.
 */
float segmento(vec3 ro, vec3 rd, vec3 c, vec3 e, float L, float r, float ang, float folga, out float t) {
    vec3 w = ro - c;
    float b = dot(rd, e), dd = dot(rd, w), ee = dot(e, w);
    float den = max(1.0 - b * b, 1e-6);
    float s = (ee - b * dd) / den;                     // onde, na reta do segmento, o raio passa mais perto
    vec3 q = c + e * s;
    t = dot(q - ro, rd);
    if (t <= 0.0) return 0.0;
    float px = t * ang;
    float dist = length(ro + rd * t - q);
    // (medido: a linha fina nunca some — tem pelo menos 1.17 px de largura)
    float lado = clamp((max(r, 0.5 * 1.17 * px) + folga * px - dist) / px + 0.5, 0.0, 1.0);
    float ponta = clamp((L - abs(s)) / (px / max(sqrt(den), 0.05)) + 0.5, 0.0, 1.0);
    return lado * ponta;
}

float esfera(vec3 ro, vec3 rd, vec3 c, float r, float ang, out float t) {
    vec3 oc = c - ro;
    t = dot(oc, rd);
    if (t <= 0.0) return 0.0;
    float px = t * ang;
    return clamp((r - sqrt(max(dot(oc, oc) - t * t, 0.0))) / px + 0.5, 0.0, 1.0);
}

float caixa(vec3 ro, vec3 rd, vec3 c, vec3 h, out float t) {
    vec3 inv = 1.0 / (abs(rd) + 1e-9) * sign(rd + 1e-12);
    vec3 a = (c - h - ro) * inv, b = (c + h - ro) * inv;
    vec3 mn = min(a, b), mx = max(a, b);
    float t0 = max(mn.x, max(mn.y, mn.z)), t1 = min(mx.x, min(mx.y, mx.z));
    t = t0;
    return t1 >= max(t0, 0.0) ? 1.0 : 0.0;
}

/** Um sorteio 0..1 por elemento e por canal; a Phase faz ele andar devagar, sem pular. */
float sorteio(vec3 cel, float canal) {
    vec3 p = fract((cel + vec3(seed * 0.731, seed * 1.377, canal * 7.13)) * vec3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yxz + 33.33);
    float h = fract((p.x + p.y) * p.z), h2 = fract((p.x + p.z) * p.y);
    return abs(fract(h + phase / 360.0 * (0.3 + 0.7 * h2)) * 2.0 - 1.0);
}

mat3 giroDe(vec3 graus) {
    vec3 a = radians(graus), s = sin(a), c = cos(a);
    return mat3(c.z, s.z, 0.0, -s.z, c.z, 0.0, 0.0, 0.0, 1.0) * mat3(c.y, 0.0, -s.y, 0.0, 1.0, 0.0, s.y, 0.0, c.y) * mat3(1.0, 0.0, 0.0, 0.0, c.x, s.x, 0.0, -s.x, c.x);
}

/** Um plano do Crop: 1 dentro, caindo a 0 ao longo de `cropFade` para fora. `d` = quanto o ponto está para dentro. */
float corte(bool ligado, float d) {
    if (!ligado) return 1.0;
    return cropFade > 0.5 ? clamp(d / cropFade + 1.0, 0.0, 1.0) : step(0.0, d);
}

void main() {
    vec2 uv = acScreenNorm;
    vec4 orig = texture(inputImg, uv);
    vec2 R = tamanho() / acEscalaDePixel;               // o quadro em px da composição: a unidade do mundo
    vec2 p = uv * R;

    // O RAIO. Medido: sem câmera na composição, o olho do plugin fica na ORIGEM do mundo (o canto do
    // quadro, z = 0) olhando para +z, com 60° de campo vertical, e o centro da imagem é o eixo dele.
    // Com câmera, ele usa a posição e o giro dela, mas com o foco = zoom × altura / 1920 (não é o
    // campo de visão da câmera do AE — repetido aqui para dar a mesma imagem).
    vec3 ro, rd, frente, direita, baixo;
    if (acCamera3D == 1) {
        vec2 tela = acTela(uv);
        vec3 dc = (acCameraInvVP * vec4(0.0, 0.0, 1.0, 1.0)).xyz;
        vec3 dx = (acCameraInvVP * vec4(1.0, 0.0, 1.0, 1.0)).xyz - dc, dy = (acCameraInvVP * vec4(0.0, -1.0, 1.0, 1.0)).xyz - dc;
        dc -= acCameraOlhoNova;
        frente = normalize(dc); direita = normalize(dx); baixo = normalize(dy);
        rd = dc + (dx * (tela.x * 2.0 - 1.0) + dy * (tela.y * 2.0 - 1.0)) * (1920.0 / R.y);
        ro = acCameraOlho;
    } else {
        ro = vec3(0.0);
        frente = vec3(0.0, 0.0, 1.0); direita = vec3(1.0, 0.0, 0.0); baixo = vec3(0.0, 1.0, 0.0);
        rd = vec3(p - 0.5 * R, FOCO * R.y);
    }
    rd = normalize(rd);
    float ang = max(length(dFdx(rd)), length(dFdy(rd)));        // o tamanho angular de um pixel

    // A GRADE, no espaço dela: gira e estica em volta do canto da grade (medido: 50 − Offset em X e Y, −Offset Z).
    float S = max(spacing, 1.0);
    vec3 esc = (uniformScale ? vec3(scaleX) : vec3(scaleX, scaleY, scaleZ)) / 100.0;
    mat3 M = giro();
    // (medido com a câmera girada: o plugin aplica esse canto nos eixos da CÂMERA, não nos do mundo)
    vec3 canto = vec3(50.0 - offsetXY * R, -offsetZ);
    vec3 pivo = direita * canto.x + baixo * canto.y + frente * canto.z;
    vec3 o = transpose(M) * (ro - pivo) / esc + pivo;
    vec3 d = transpose(M) * rd / esc;
    float estica = length(d);                                  // (unidades da grade por unidade do mundo, ao longo do raio)
    d /= estica;
    float angG = ang * estica;
    vec3 base = pivo + 0.5 * S;                                // os pontos da grade: de S em S a partir daqui

    vec3 cel = floor((o - base) / S + 0.5);
    vec3 passo = sign(d + 1e-12);
    vec3 inv = 1.0 / (abs(d) + 1e-9) * passo;
    vec3 tProx = ((cel + 0.5 * passo) * S + base - o) * inv;
    vec3 tDelta = abs(S * inv);
    vec3 acum = vec3(0.0); float alfa = 0.0;
    float tCel = 0.0;
    bool aleatorio = randomPosition + randomScale + randomRotation + randomVisibility + randomColor + randomOpacity > 0.0;
    for (int n = 0; n < PASSOS; n++) {
        if (tCel / estica > depth * 1.8 + 2.0 * S || alfa > 0.995) break;
        vec3 c = cel * S + base;
        float raio = 0.5 * elementScale, a0 = opacity / 100.0;
        vec3 cor = color.rgb;
        mat3 G = mat3(1.0);
        bool some = false;
        if (aleatorio) {
            // Random (as faixas foram medidas com pontos; o sorteio em si é outro)
            some = sorteio(cel, 1.0) < randomVisibility / 100.0;
            raio *= max(0.1, 1.0 + (2.0 * sorteio(cel, 2.0) - 1.0) * 0.6 * randomScale / 100.0);
            a0 *= 1.0 - sorteio(cel, 3.0) * randomOpacity / 100.0;
            cor = mix(cor, vec3(sorteio(cel, 4.0), sorteio(cel, 5.0), sorteio(cel, 6.0)), randomColor / 100.0);
            // (a posição sorteada fica dentro da própria célula — é o que o raio consegue achar)
            vec3 desvio = vec3(sorteio(cel, 7.0), sorteio(cel, 8.0), sorteio(cel, 9.0)) * 2.0 - 1.0;
            c += desvio * min(randomPosition / 100.0, 1.0) * max(0.5 * S - raio, 0.0);
            if (randomRotation > 0.0) G = giroDe((vec3(sorteio(cel, 10.0), sorteio(cel, 11.0), sorteio(cel, 12.0)) * 2.0 - 1.0) * randomRotation * 2.0);
        }
        vec3 doOlho = M * ((c - pivo) * esc) + pivo - ro;       // o elemento, visto do olho, no mundo
        float longe = length(doOlho), z = dot(doOlho, frente);
        // Crop (medido): planos a partir do canto da grade, no espaço da câmera (Camera View) ou no do mundo
        vec3 pc = cameraView ? vec3(dot(doOlho, direita), dot(doOlho, baixo), z) : doOlho + ro;
        float recorte = corte(cropXn, pc.x - (canto.x - xn)) * corte(cropXp, (canto.x + xp) - pc.x)
                      * corte(cropYn, pc.y - (canto.y - yn)) * corte(cropYp, (canto.y + yp) - pc.y)
                      * corte(cropZn, pc.z - (canto.z - zn)) * corte(cropZp, (canto.z + zp) - pc.z);
        // Depth Fade (medido): linear nos últimos `fade` antes do Depth, contado no eixo da câmera
        float some2 = clamp((depth - z) / max(depthFade, 1e-3), 0.0, 1.0) * a0 * recorte;
        if (!some && z > 0.0 && z < depth && some2 > 0.0) {
            float t;
            vec3 ol = transpose(G) * (o - c) + c, dl = transpose(G) * d;       // o raio no espaço do elemento
            if (patternType == 2) {
                float a = esfera(o, d, c, raio * 1.05, angG, t) * some2;
                acum += (1.0 - alfa) * a * cor; alfa += (1.0 - alfa) * a;
            } else if (patternType == 4) {
                float a = caixa(ol, dl, c, vec3(raio), t) * some2;
                acum += (1.0 - alfa) * a * cor; alfa += (1.0 - alfa) * a;
            } else if (patternType == 3 && longe < depth) {
                // CRUZ: três braços nos eixos, cada um pintado por cima do outro (medido: no cruzamento a
                // opacidade é 1 − (1 − a)³). Com Cross Width são caixas de ponta reta; sem, um fio de
                // largura fixa na tela. Medido: a cruz some além do Depth em RAIO, não em plano.
                float h = 0.5 * crossWidth;
                bool grosso = h > 0.75 * max(dot(c - o, d), 0.0) * angG;
                for (int e = 0; e < 3; e++) {
                    vec3 eixo = e == 0 ? vec3(1.0, 0.0, 0.0) : e == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0);
                    float a = (grosso ? caixa(ol, dl, c, eixo * (raio - h) + h, t) : segmento(ol, dl, c, eixo, raio, h, angG, 0.0, t)) * some2;
                    acum += (1.0 - alfa) * a * cor; alfa += (1.0 - alfa) * a;
                }
            }
        }
        if (patternType < 2) {
            // LINHAS (só em X) e GRADE (nos três eixos): retas inteiras pelos pontos da grade, de largura
            // = Scale, com 0.6 px a mais de cada lado (medido).
            for (int e = 0; e < 3; e++) {
                if (patternType == 0 && e != 0) break;
                vec3 eixo = e == 0 ? vec3(1.0, 0.0, 0.0) : e == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0);
                float t;
                float a = segmento(o, d, c, eixo, 0.5 * S, 0.5 * elementScale, angG, 0.6, t);
                if (a <= 0.0) continue;
                vec3 q = M * ((o + d * t - pivo) * esc) + pivo - ro;
                float zq = dot(q, frente);
                if (zq <= 0.0 || length(q) > depth) continue;
                a *= clamp((depth - zq) / max(depthFade, 1e-3), 0.0, 1.0) * opacity / 100.0;
                acum += (1.0 - alfa) * a * color.rgb; alfa += (1.0 - alfa) * a;
            }
        }
        // anda para a próxima célula
        if (tProx.x < tProx.y && tProx.x < tProx.z) { tCel = tProx.x; tProx.x += tDelta.x; cel.x += passo.x; }
        else if (tProx.y < tProx.z) { tCel = tProx.y; tProx.y += tDelta.y; cel.y += passo.y; }
        else { tCel = tProx.z; tProx.z += tDelta.z; cel.z += passo.z; }
    }
    vec4 saida = vec4(alfa > 0.0 ? acum / alfa : vec3(0.0), alfa);
    if (compositeOnOriginal) {
        float a = saida.a + orig.a * (1.0 - saida.a);
        saida = vec4(a > 0.0 ? (saida.rgb * saida.a + orig.rgb * orig.a * (1.0 - saida.a)) / a : vec3(0.0), a);
    }
    fragColor = saida;
}
